/* 查表：返回码点对应字形，未收录返回 NULL（调用方画全填方块兜底） */
static inline const glyph_t* font_find(uint32_t cp) {
    for (uint32_t i = 0; i < FONT_GLYPH_COUNT; i++) {
        if (FONT_GLYPHS[i].cp == cp) return &FONT_GLYPHS[i];
    }
    return 0;
}

